import{state}from"./state.js";import{renderShop,renderRequests}from"./ui.js";import{showToast,showConfirm,showMobileEventNotification,escapeHtml}from"./utils.js";import{scheduleSave,addHistoryEntry,checkDailyCoinLimit,getActingChildId,updateBalanceLocally,addRequestEntry,checkFrequency}from"./action-helpers.js";import{triggerTaskAnimation}from"./motion-feedback.js";export function earnCoins(e){const i=state.tasks.find(i=>i.id==e);if(!i)return;const t="admin"===state.role?state.currentChildId:state.children[0]?.id||null;if(!t){const e=state.isAdmin&&0===state.children.length?"Сначала добавьте ребенка":"Сначала выберите ребенка";return showToast(e,"error")}const n=[checkFrequency(i,t),checkDailyCoinLimit(t,i.coins)].filter(Boolean),o=()=>{updateBalanceLocally(t,i.coins),addHistoryEntry({type:"earn",amount:i.coins,description:i.name,group:i.group,comment:i.comment,relatedId:i.id,childIdOverride:t}),renderShop(),showMobileEventNotification(`+${i.coins} мон. начислено!`,"success","Balance updated"),triggerTaskAnimation()};if(n.length>0)return showConfirm("Превышен лимит",`${n.join(". ")}. Все равно начислить?`,{onConfirm:o});const s=`Подтвердить выполнение задания "${escapeHtml(i.name)}" за ${i.coins} <span class="gamified-icon icon-coin-stack" aria-hidden="true" style="width: 1.2rem; height: 1.2rem; vertical-align: middle;"></span>?`;showConfirm("Выполнить задание?",s,{onConfirm:o})}export function requestCoins(e){const i=state.tasks.find(i=>i.id==e);if(!i)return;const t=getActingChildId();if(!t)return showToast("Сначала выберите ребенка","error");const n=[checkFrequency(i,t),checkDailyCoinLimit(t,i.coins)].filter(Boolean);if(n.length>0)return showConfirm("Лимит исчерпан",n.join(". "),{cancelLabel:"Понятно",hideConfirm:!0});const o=`"${escapeHtml(i.name)}" за ${i.coins} <span class="gamified-icon icon-coin-stack" aria-hidden="true" style="width: 1.2rem; height: 1.2rem; vertical-align: middle;"></span>`;showConfirm("Отправить заявку?",o,{onConfirm:()=>{addRequestEntry({childId:t,requestType:"earn",taskId:i.id,taskName:i.name,coins:i.coins}),scheduleSave(),renderRequests(),document.querySelector('.nav__btn[data-tab="requests"]')?.click(),showMobileEventNotification("Заявка отправлена!","success","Новая заявка"),triggerTaskAnimation()}})}